            while (not (obj.ReferenceEquals(inlet, null))) do
                inletValid <- 0
                i <- inlet.linkIndex
                xsect <- Link.[i].xsect
                inletType <- InletDesigns.[inlet.designIndex].type_
                if (inletType = CUSTOM_INLET) then
                    j <- InletDesigns.[inlet.designIndex].customCurve
                    if (j >= 0) then
                        if ((Curve.[j].curveType = DIVERSION_CURVE) || (Curve.[j].curveType = RATING_CURVE)) then
                            inletValid <- 1
                elif ((((xsect.type_ = TRAPEZOIDAL) || (xsect.type_ = RECT_OPEN))) && (((inletType = DROP_GRATE_INLET) || (inletType = DROP_CURB_INLET)))) then
                    inletValid <- 1
                elif (((xsect.type_ = STREET_XSECT) && (inletType <> DROP_GRATE_INLET)) && (inletType <> DROP_CURB_INLET)) then
                    inletValid <- 1
                if (inletValid <> 0) then
                    Node.[Link.[i].node2].inlet <- BYPASS
                    Node.[inlet.nodeIndex].inlet <- CAPTURE
                    inlet.backflow <- 0.0
                    S.getConduitGeometry(inlet)
                    inlet.flowFactor <- ((((0.56 / n)) * Libm.pow(SL, 0.5)) * Libm.pow(Sx, 1.67))
                    prevInlet <- inlet
                    inlet <- inlet.nextInlet
                else
                    S.report_writeWarningMsg(L187, Link.[i].ID)
                    if (obj.ReferenceEquals(inlet, FirstInlet)) then
                        FirstInlet <- inlet.nextInlet
                        prevInlet <- FirstInlet
                        inlet <- FirstInlet
                    else
                        prevInlet.nextInlet <- inlet.nextInlet
                        inlet <- prevInlet.nextInlet
