    // inlet.c:555
    static member inlet_findCapturedFlows (tStep: float) : unit =
        let mutable i : int = 0
        let mutable j : int = 0
        let mutable m : int = 0
        let mutable placement : int = 0
        let mutable q : float = 0.0
        let mutable inlet : TInlet = Unchecked.defaultof<TInlet>
        if (not (UsesInlets <> 0)) then
            ()
        else
            R.memset(InletFlow, 0, (uint64 (Nobjects.[NODE]) * 8UL))
            if (RouteModel <> DW) then
                j <- 0
                while (j < Nobjects.[NODE]) do
                    Node.[j].inflow <- ((if (((0.0) >= (Node.[j].newLatFlow))) then (0.0) else (Node.[j].newLatFlow)))
                    j <- j + 1
                i <- 0
                while (i < Nobjects.[LINK]) do
                    Node.[Link.[i].node2].inflow <- (Node.[Link.[i].node2].inflow + ((if (((0.0) >= (Link.[i].newFlow))) then (0.0) else (Link.[i].newFlow))))
                    i <- i + 1
            inlet <- FirstInlet
            while (not (obj.ReferenceEquals(inlet, null))) do
                i <- inlet.linkIndex
                j <- Link.[i].node2
                m <- inlet.nodeIndex
                placement <- S.getInletPlacement(inlet, j)
                if (InletDesigns.[inlet.designIndex].type_ = CUSTOM_INLET) then
                    q <- Math.Abs(Link.[i].newFlow)
                    inlet.flowCapture <- S.getCustomCapturedFlow(inlet, q, Node.[j].newDepth)
                elif (placement = ON_GRADE) then
                    q <- Math.Abs(Link.[i].newFlow)
                    inlet.flowCapture <- S.getOnGradeCapturedFlow(inlet, q, Node.[j].newDepth)
                else
                    q <- Node.[j].inflow
                    inlet.flowCapture <- S.getOnSagCapturedFlow(inlet, q, Node.[j].newDepth)
                if (Math.Abs(inlet.flowCapture) < 0.0001) then
                    inlet.flowCapture <- 0.0
                InletFlow.[j] <- (InletFlow.[j] + inlet.flowCapture)
                inlet.backflow <- (Node.[m].overflow * inlet.backflowRatio)
                if (Math.Abs(inlet.backflow) < 0.0001) then
                    inlet.backflow <- 0.0
                inlet <- inlet.nextInlet
            inlet <- FirstInlet
            while (not (obj.ReferenceEquals(inlet, null))) do
                i <- inlet.linkIndex
                j <- Link.[i].node2
                m <- inlet.nodeIndex
                if ((RouteModel <> DW) && (S.getInletPlacement(inlet, j) = ON_SAG)) then
                    q <- (Node.[j].newVolume / tStep)
                    q <- (q + ((if (((Node.[j].inflow) >= (0.0))) then (Node.[j].inflow) else (0.0))))
                    if (InletFlow.[j] > q) then
                        inlet.flowCapture <- (inlet.flowCapture * (q / InletFlow.[j]))
                Node.[j].newLatFlow <- (Node.[j].newLatFlow - ((inlet.flowCapture - inlet.backflow)))
                Node.[m].newLatFlow <- (Node.[m].newLatFlow + inlet.flowCapture)
                if (S.getDateTime(NewRoutingTime) > ReportStart) then
                    S.updateInletStats(inlet, Math.Abs(Link.[i].newFlow))
                inlet <- inlet.nextInlet

