    // inlet.c:985
    static member updateInletStats (inlet: TInlet, q: float) : unit =
        let mutable qCapture : float = 0.0
        let mutable qBackflow : float = 0.0
        let mutable qNet : float = 0.0
        let mutable qBypass : float = 0.0
        let mutable fCapture : float = 0.0
        qCapture <- inlet.flowCapture
        qBackflow <- inlet.backflow
        qNet <- (qCapture - qBackflow)
        qBypass <- (q - qNet)
        fCapture <- 0.0
        if ((q < 0.001) && (qBackflow <= 0.0)) then
            ()
        else
            inlet.stats.flowPeriods <- inlet.stats.flowPeriods + 1
            if (qNet > 0.0) then
                inlet.stats.capturePeriods <- inlet.stats.capturePeriods + 1
                fCapture <- (qNet / q)
                fCapture <- ((if (((fCapture) <= (1.0))) then (fCapture) else (1.0)))
                inlet.stats.avgFlowCapture <- (inlet.stats.avgFlowCapture + fCapture)
                if (qBypass > 0.001) then
                    inlet.stats.bypassFreq <- inlet.stats.bypassFreq + 1.0
            else
                inlet.stats.backflowPeriods <- inlet.stats.backflowPeriods + 1
            if (q > inlet.stats.peakFlow) then
                inlet.stats.peakFlow <- q
                inlet.stats.peakFlowCapture <- (fCapture * 100.0)

