        elif (buildup >= c0) then
            __rv <- Landuse.[i].buildupFunc.[p].maxDays
        else
            match Landuse.[i].buildupFunc.[p].funcType with
            | 1 ->
                if ((c1 * c2) = 0.0) then
                    __rv <- 0.0
                else
                    __rv <- Libm.pow(((buildup / c1)), ((1.0 / c2)))
            | 2 ->
                if ((c0 * c1) = 0.0) then
                    __rv <- 0.0
                else
                    __rv <- ((-(Libm.log((1.0 - (buildup / c0))))) / c1)
            | 3 ->
                if (c0 = 0.0) then
                    __rv <- 0.0
                else
                    __rv <- ((buildup * c2) / ((c0 - buildup)))
            | _ ->
                __rv <- 0.0
        __rv

