            | 1 ->
                b <- (c1 * Libm.pow(days, c2))
                if (b > c0) then
                    b <- c0
            | 2 ->
                b <- (c0 * ((1.0 - Libm.exp(((-(days)) * c1)))))
            | 3 ->
                b <- ((days * c0) / ((c2 + days)))
            | _ ->
                b <- 0.0
            __rv <- b
        __rv

