    // landuse.c:553
    static member landuse_getWashoffLoad (i: int, p: int, area: float, landFactor: TLandFactor[], runoff: float, vOutflow: float) : float =
        let mutable __rv : float = 0.0
        let mutable landuseArea : float = 0.0
        let mutable buildup : float = 0.0
        let mutable washoffQual : float = 0.0
        let mutable washoffLoad : float = 0.0
        let mutable bmpRemoval : float = 0.0
        buildup <- landFactor.[i].buildup.[p]
        landuseArea <- (landFactor.[i].fraction * area)
        washoffQual <- S.landuse_getWashoffQual(i, p, buildup, runoff, landuseArea)
        washoffLoad <- ((((washoffQual * vOutflow) * landuseArea) / area) * Pollut.[p].mcf)
        if ((Landuse.[i].buildupFunc.[p].funcType <> NO_BUILDUP) || (buildup > washoffLoad)) then
            washoffLoad <- ((if (((washoffLoad) <= (buildup))) then (washoffLoad) else (buildup)))
            buildup <- (buildup - washoffLoad)
            landFactor.[i].buildup.[p] <- buildup
        else
            S.massbal_updateLoadingTotals(BUILDUP_LOAD, p, washoffLoad)
            landFactor.[i].buildup.[p] <- 0.0
        bmpRemoval <- (Landuse.[i].washoffFunc.[p].bmpEffic * washoffLoad)
        if (bmpRemoval > 0.0) then
            S.massbal_updateLoadingTotals(BMP_REMOVAL_LOAD, p, bmpRemoval)
            washoffLoad <- (washoffLoad - bmpRemoval)
        __rv <- (washoffLoad / Pollut.[p].mcf)
        __rv

    // landuse.c:612
    static member landuse_getWashoffQual (i: int, p: int, buildup: float, runoff: float, area: float) : float =
        let mutable __rv : float = 0.0
        let mutable cWashoff : float = 0.0
        let mutable coeff : float = 0.0
        let mutable expon : float = 0.0
        let mutable func : int = 0
        cWashoff <- 0.0
        coeff <- Landuse.[i].washoffFunc.[p].coeff
        expon <- Landuse.[i].washoffFunc.[p].expon
        func <- Landuse.[i].washoffFunc.[p].funcType
        if ((func = NO_WASHOFF) || (runoff = 0.0)) then
            __rv <- 0.0
        elif ((Landuse.[i].buildupFunc.[p].funcType <> NO_BUILDUP) && (buildup = 0.0)) then
            __rv <- 0.0
        else
            if (func = EXPON_WASHOFF) then
                cWashoff <- (((coeff * Libm.pow((runoff * S.UCF(RAINFALL)), expon)) * buildup) / Pollut.[p].mcf)
                cWashoff <- (cWashoff / (runoff * area))
            elif (func = RATING_WASHOFF) then
                cWashoff <- (coeff * Libm.pow((runoff * area), (expon - 1.0)))
            elif (func = EMC_WASHOFF) then
                cWashoff <- coeff
            __rv <- cWashoff
        __rv

