    // lid.c:932
    static member validateLidProc (j: int) : unit =
        let mutable layerMissing : int = 0
        layerMissing <- 0
        if (LidProcs.[j].lidType < 0) then
            S.report_writeErrorMsg(ERR_LID_TYPE, LidProcs.[j].ID)
        else
            match LidProcs.[j].lidType with
            | 0 | 1 ->
                if (LidProcs.[j].soil.thickness <= 0.0) then
                    layerMissing <- 1
            | 2 ->
                if (LidProcs.[j].soil.thickness <= 0.0) then
                    layerMissing <- 1
                if (LidProcs.[j].drainMat.thickness <= 0.0) then
                    layerMissing <- 1
            | 4 ->
                if (LidProcs.[j].pavement.thickness <= 0.0) then
                    layerMissing <- 1
            | 3 ->
                if (LidProcs.[j].storage.thickness <= 0.0) then
                    layerMissing <- 1
            | _ ->
                ()
            if (layerMissing <> 0) then
                S.report_writeErrorMsg(ERR_LID_LAYER, LidProcs.[j].ID)
            else
                if (LidProcs.[j].lidType = POROUS_PAVEMENT) then
                    if (((((LidProcs.[j].pavement.thickness <= 0.0) || (LidProcs.[j].pavement.kSat <= 0.0)) || (LidProcs.[j].pavement.voidFrac <= 0.0)) || (LidProcs.[j].pavement.voidFrac > 1.0)) || (LidProcs.[j].pavement.impervFrac > 1.0)) then
                        ignore (O.sstrncpy(Msg, LidProcs.[j].ID, uint64 (1024)))
                        ignore (O.sstrcat(Msg, L284, uint64 (1024)))
                        S.report_writeErrorMsg(ERR_LID_PARAMS, Msg)
                if (LidProcs.[j].soil.thickness > 0.0) then
                    if (((((LidProcs.[j].soil.porosity <= 0.0) || (LidProcs.[j].soil.fieldCap >= LidProcs.[j].soil.porosity)) || (LidProcs.[j].soil.wiltPoint >= LidProcs.[j].soil.fieldCap)) || (LidProcs.[j].soil.kSat <= 0.0)) || (LidProcs.[j].soil.kSlope < 0.0)) then
                        ignore (O.sstrncpy(Msg, LidProcs.[j].ID, uint64 (1024)))
                        ignore (O.sstrcat(Msg, L285, uint64 (1024)))
                        S.report_writeErrorMsg(ERR_LID_PARAMS, Msg)
                if (LidProcs.[j].storage.thickness > 0.0) then
                    if ((LidProcs.[j].storage.voidFrac <= 0.0) || (LidProcs.[j].storage.voidFrac > 1.0)) then
                        ignore (O.sstrncpy(Msg, LidProcs.[j].ID, uint64 (1024)))
                        ignore (O.sstrcat(Msg, L286, uint64 (1024)))
                        S.report_writeErrorMsg(ERR_LID_PARAMS, Msg)
                else
                    LidProcs.[j].storage.voidFrac <- 1.0
                    LidProcs.[j].drain.offset <- 0.0
                if ((LidProcs.[j].drain.hOpen > 0.0) && (LidProcs.[j].drain.hOpen <= LidProcs.[j].drain.hClose)) then
                    ignore (O.sstrncpy(Msg, LidProcs.[j].ID, uint64 (1024)))
                    ignore (O.sstrcat(Msg, L287, uint64 (1024)))
                    S.report_writeErrorMsg(ERR_LID_PARAMS, Msg)
                if (LidProcs.[j].lidType = VEG_SWALE) then
                    if (((LidProcs.[j].surface.roughness * LidProcs.[j].surface.surfSlope) <= 0.0) || (LidProcs.[j].surface.thickness = 0.0)) then
                        ignore (O.sstrncpy(Msg, LidProcs.[j].ID, uint64 (1024)))
                        ignore (O.sstrcat(Msg, L288, uint64 (1024)))
                        S.report_writeErrorMsg(ERR_LID_PARAMS, Msg)
                    else
                        LidProcs.[j].surface.alpha <- ((1.49 * Math.Sqrt(LidProcs.[j].surface.surfSlope)) / LidProcs.[j].surface.roughness)
                elif (LidProcs.[j].surface.roughness > 0.0) then
                    LidProcs.[j].surface.alpha <- ((1.49 / LidProcs.[j].surface.roughness) * Math.Sqrt(LidProcs.[j].surface.surfSlope))
                else
                    LidProcs.[j].surface.alpha <- 0.0
                if (LidProcs.[j].drainMat.roughness > 0.0) then
                    LidProcs.[j].drainMat.alpha <- ((1.49 / LidProcs.[j].drainMat.roughness) * Math.Sqrt(LidProcs.[j].surface.surfSlope))
                else
                    LidProcs.[j].drainMat.alpha <- 0.0
                if (LidProcs.[j].pavement.thickness > 0.0) then
                    LidProcs.[j].pavement.clogFactor <- (LidProcs.[j].pavement.clogFactor * ((LidProcs.[j].pavement.thickness * LidProcs.[j].pavement.voidFrac) * ((1.0 - LidProcs.[j].pavement.impervFrac))))
                if (LidProcs.[j].storage.thickness > 0.0) then
                    LidProcs.[j].storage.clogFactor <- (LidProcs.[j].storage.clogFactor * (LidProcs.[j].storage.thickness * LidProcs.[j].storage.voidFrac))
                else
                    LidProcs.[j].storage.clogFactor <- 0.0
                LidProcs.[j].surface.canOverflow <- 1
                match LidProcs.[j].lidType with
                | 7 ->
                    LidProcs.[j].surface.canOverflow <- 0
                | 3 | 4 | 0 | 1 | 2 ->
                    if (LidProcs.[j].surface.alpha > 0.0) then
                        LidProcs.[j].surface.canOverflow <- 0
                | _ ->
                    ()
                if (LidProcs.[j].lidType = RAIN_BARREL) then
                    LidProcs.[j].storage.voidFrac <- 1.0
                    LidProcs.[j].storage.kSat <- 0.0
                if (LidProcs.[j].lidType = GREEN_ROOF) then
                    LidProcs.[j].storage.thickness <- LidProcs.[j].drainMat.thickness
                    LidProcs.[j].storage.voidFrac <- LidProcs.[j].drainMat.voidFrac
                    LidProcs.[j].storage.clogFactor <- 0.0
                    LidProcs.[j].storage.kSat <- 0.0

