    static member evalLidUnit (j: int, lidUnit: TLidUnit, lidArea: float, lidInflow: float, tStep: float, qRunoff: byref<float>, qDrain: byref<float>, qReturn: byref<float>) : unit =
        let mutable lidProc : TLidProc = Unchecked.defaultof<TLidProc>
