        lidDrain <- (lidDrain * lidArea)
        if ((lidUnit.toPerv <> 0) && (Subcatch.[j].area > Subcatch.[j].lidArea)) then
            qReturn <- (qReturn + lidRunoff)
            lidRunoff <- 0.0
            if ((lidUnit.drainNode = Subcatch.[j].outNode) && (lidUnit.drainSubcatch = Subcatch.[j].outSubcatch)) then
                qReturn <- (qReturn + lidDrain)
                lidDrain <- 0.0
        if (lidUnit.drainNode >= 0) then
            S.massbal_updateRunoffTotals(RUNOFF_DRAINS, (lidDrain * tStep))
        lidUnit.newDrainFlow <- lidDrain
        Vevap <- (Vevap + ((lidEvap * tStep) * lidArea))
        VlidInfil <- (VlidInfil + ((lidInfil * tStep) * lidArea))
        if (S.isLidPervious(lidUnit.lidIndex) <> 0) then
