                Node.[n_2].fullDepth <- ((if (((Node.[n_2].fullDepth) >= ((Link.[j].offset1 + Link.[j].xsect.yFull)))) then (Node.[n_2].fullDepth) else ((Link.[j].offset1 + Link.[j].xsect.yFull))))
            n_2 <- Link.[j].node2
            if ((((Node.[n_2].type_ <> STORAGE) || (Node.[n_2].surDepth > 0.0))) && (Link.[j].type_ = CONDUIT)) then
                Node.[n_2].fullDepth <- ((if (((Node.[n_2].fullDepth) >= ((Link.[j].offset2 + Link.[j].xsect.yFull)))) then (Node.[n_2].fullDepth) else ((Link.[j].offset2 + Link.[j].xsect.yFull))))

