    static member outlet_getInflow (j: int) : float =
        let mutable __rv : float = 0.0
        let mutable k : int = 0
        let mutable n1 : int = 0
        let mutable n2 : int = 0
        let mutable head : float = 0.0
        let mutable hcrest : float = 0.0
        let mutable h1 : float = 0.0
        let mutable h2 : float = 0.0
        let mutable y1 : float = 0.0
        let mutable dir : float = 0.0
        n1 <- Link.[j].node1
        n2 <- Link.[j].node2
        k <- Link.[j].subIndex
        if (RouteModel = DW) then
            h1 <- (Node.[n1].newDepth + Node.[n1].invertElev)
            h2 <- (Node.[n2].newDepth + Node.[n2].invertElev)
        else
            h1 <- (Node.[n1].newDepth + Node.[n1].invertElev)
            h2 <- Node.[n1].invertElev
        dir <- (if ((h1 >= h2)) then 1.0 else (-(1.0)))
        y1 <- Node.[n1].newDepth
        if (dir < 0.0) then
            y1 <- h1
            h1 <- h2
            h2 <- y1
            y1 <- Node.[n2].newDepth
        hcrest <- (Node.[n1].invertElev + Link.[j].offset1)
        if ((Outlet.[k].curveType = NODE_HEAD) && (RouteModel = DW)) then
            head <- (h1 - ((if (((h2) >= (hcrest))) then (h2) else (hcrest))))
        else
            head <- (h1 - hcrest)
        if (((head <= 0.0001) || (y1 <= 0.0001)) || (S.link_setFlapGate(j, n1, n2, dir) <> 0)) then
            Link.[j].newDepth <- 0.0
            Link.[j].flowClass <- DRY
            __rv <- 0.0
        else
            Link.[j].newDepth <- head
            Link.[j].flowClass <- SUBCRITICAL
            __rv <- ((dir * Link.[j].setting) * S.outlet_getFlow(k, head))
        __rv

    // link.c:2672
    static member outlet_getFlow (k: int, head: float) : float =
        let mutable __rv : float = 0.0
        let mutable m : int = 0
        let mutable h : float = 0.0
        h <- (head * S.UCF(LENGTH))
        m <- Outlet.[k].qCurve
        if (m >= 0) then
            __rv <- (S.table_lookup(Curve.[m], h) / S.UCF(FLOW))
        else
            __rv <- ((Outlet.[k].qCoeff * Libm.pow(h, Outlet.[k].qExpon)) / S.UCF(FLOW))
        __rv

