        sysFlows.[SYS_EXFLOW] <- ((((f1 * OldStepFlowTotals.exInflow) + (f * StepFlowTotals.exInflow))) * S.UCF(FLOW))
        sysFlows.[SYS_FLOODING] <- ((((f1 * OldStepFlowTotals.flooding) + (f * StepFlowTotals.flooding))) * S.UCF(FLOW))
        sysFlows.[SYS_OUTFLOW] <- ((((f1 * OldStepFlowTotals.outflow) + (f * StepFlowTotals.outflow))) * S.UCF(FLOW))
