    // node.c:200
    static member node_validate (j: int) : unit =
        let mutable inflow : TDwfInflow = Unchecked.defaultof<TDwfInflow>
        if ((Node.[j].fullDepth > Node.[j].oldDepth) && (Node.[j].oldDepth > 0.0)) then
            S.report_writeWarningMsg(L317, Node.[j].ID)
        if (Node.[j].initDepth > (Node.[j].fullDepth + Node.[j].surDepth)) then
            S.report_writeErrorMsg(ERR_NODE_DEPTH, Node.[j].ID)
        if (Node.[j].type_ = STORAGE) then
            if (S.node_getVolume(j, Node.[j].fullDepth) < 0.0) then
                S.report_writeErrorMsg(ERR_STORAGE_VOLUME, Node.[j].ID)
        if (Node.[j].type_ = DIVIDER) then
            S.divider_validate(j)
        inflow <- Node.[j].dwfInflow
        while (not (obj.ReferenceEquals(inflow, null))) do
            S.inflow_initDwfInflow(inflow)
            inflow <- inflow.next

