    // qualrout.c:100
    static member qualrout_execute (tStep: float) : unit =
        let mutable i : int = 0
        let mutable j : int = 0
        let mutable qIn : float = 0.0
        let mutable vAvg : float = 0.0
        i <- 0
        while (i < Nobjects.[LINK]) do
            S.findLinkMassFlow(i, tStep)
            i <- i + 1
        j <- 0
        while (j < Nobjects.[NODE]) do
            Node.[j].qualInflow <- Node.[j].inflow
            qIn <- Node.[j].qualInflow
            vAvg <- (((Node.[j].oldVolume + Node.[j].newVolume)) / 2.0)
            if (not (obj.ReferenceEquals(Node.[j].treatment, null))) then
                if (qIn < 1.0e-10) then
                    qIn <- 0.0
                S.treatmnt_setInflow(qIn, Node.[j].newQual)
            if ((Node.[j].type_ = STORAGE) || (Node.[j].oldVolume > ZeroVolume)) then
                S.findStorageQual(j, tStep)
            else
                S.findNodeQual(j)
            if (not (obj.ReferenceEquals(Node.[j].treatment, null))) then
                S.treatmnt_treat(j, qIn, vAvg, tStep)
            j <- j + 1
        i <- 0
        while (i < Nobjects.[LINK]) do
            S.findLinkQual(i, tStep)
            i <- i + 1

    // qualrout.c:146
    static member getMixedQual (c: float, v1: float, wIn: float, qIn: float, tStep: float) : float =
        let mutable c = c
        let mutable __rv : float = 0.0
        let mutable vIn : float = 0.0
        let mutable cIn : float = 0.0
        let mutable cMax : float = 0.0
        if (qIn <= 1.0e-10) then
            __rv <- c
        else
            vIn <- (qIn * tStep)
            cIn <- ((wIn * tStep) / vIn)
            cMax <- ((if (((c) >= (cIn))) then (c) else (cIn)))
            c <- ((((c * v1) + (wIn * tStep))) / ((v1 + vIn)))
            c <- ((if (((c) <= (cMax))) then (c) else (cMax)))
            c <- ((if (((c) >= (0.0))) then (c) else (0.0)))
            __rv <- c
        __rv

    // qualrout.c:179
    static member findLinkMassFlow (i: int, tStep: float) : unit =
        let mutable j : int = 0
        let mutable p : int = 0
        let mutable qLink : float = 0.0
        let mutable w : float = 0.0
        qLink <- Link.[i].newFlow
        j <- Link.[i].node2
        if (qLink < 0.0) then
            j <- Link.[i].node1
        qLink <- Math.Abs(qLink)
        if (RouteModel <> DW) then
            qLink <- (qLink - S.inlet_capturedFlow(i))
        p <- 0
        while (p < Nobjects.[POLLUT]) do
            w <- (qLink * Link.[i].oldQual.[p])
            Node.[j].newQual.[p] <- (Node.[j].newQual.[p] + w)
            Link.[i].totalLoad.[p] <- (Link.[i].totalLoad.[p] + (w * tStep))
            p <- p + 1
        Node.[j].qualInflow <- (Node.[j].qualInflow + qLink)

    // qualrout.c:221
    static member findNodeQual (j: int) : unit =
        let mutable p : int = 0
        let mutable qNode : float = 0.0
        qNode <- Node.[j].qualInflow
        if (qNode > 1.0e-10) then
            p <- 0
            while (p < Nobjects.[POLLUT]) do
                Node.[j].newQual.[p] <- (Node.[j].newQual.[p] / qNode)
                p <- p + 1
        else
            p <- 0
            while (p < Nobjects.[POLLUT]) do
                if (Node.[j].newDepth > ZeroDepth) then
                    Node.[j].newQual.[p] <- Node.[j].oldQual.[p]
                else
                    Node.[j].newQual.[p] <- 0.0
                p <- p + 1

    // qualrout.c:253
    static member findLinkQual (i: int, tStep: float) : unit =
        let mutable j : int = 0
        let mutable k : int = 0
        let mutable p : int = 0
        let mutable wIn : float = 0.0
        let mutable qIn : float = 0.0
        let mutable qSeep : float = 0.0
        let mutable v1 : float = 0.0
        let mutable v2 : float = 0.0
        let mutable c1 : float = 0.0
        let mutable c2 : float = 0.0
        let mutable vEvap : float = 0.0
        let mutable vLosses : float = 0.0
        let mutable fEvap : float = 0.0
        let mutable barrels : float = 0.0
        j <- Link.[i].node1
        if (Link.[i].newFlow < 0.0) then
            j <- Link.[i].node2
        if ((Link.[i].type_ <> CONDUIT) || (Link.[i].xsect.type_ = DUMMY)) then
            p <- 0
            while (p < Nobjects.[POLLUT]) do
                Link.[i].newQual.[p] <- Node.[j].newQual.[p]
                p <- p + 1
        else
            k <- Link.[i].subIndex
            barrels <- float (Conduit.[k].barrels)
            qIn <- (Math.Abs(Conduit.[k].q1) * barrels)
            qSeep <- (Conduit.[k].seepLossRate * barrels)
            vEvap <- ((Conduit.[k].evapLossRate * barrels) * tStep)
            v1 <- Link.[i].oldVolume
            v2 <- Link.[i].newVolume
            vLosses <- ((qSeep * tStep) + vEvap)
            fEvap <- 1.0
            if ((vEvap > 0.0) && (v1 > ZeroVolume)) then
                fEvap <- (fEvap + (vEvap / v1))
            if (RouteModel = SF) then
                S.findSFLinkQual(i, qSeep, fEvap, tStep)
            else
                if (RouteModel = DW) then
                    qIn <- (qIn + ((((v2 + vLosses) - v1)) / tStep))
                    qIn <- ((if (((qIn) >= (0.0))) then (qIn) else (0.0)))
                p <- 0
                while (p < Nobjects.[POLLUT]) do
                    c1 <- Link.[i].oldQual.[p]
                    S.massbal_addSeepageLoss(p, (qSeep * c1))
                    c1 <- (c1 * fEvap)
                    c2 <- S.getReactedQual(p, c1, v1, tStep)
                    wIn <- (Node.[j].newQual.[p] * qIn)
                    c2 <- S.getMixedQual(c2, v1, wIn, qIn, tStep)
                    if ((v2 < ZeroVolume) || (Link.[i].newDepth <= ZeroDepth)) then
                        S.massbal_addToFinalStorage(p, (c2 * v2))
                        c2 <- 0.0
                    Link.[i].newQual.[p] <- c2
                    p <- p + 1

    // qualrout.c:357
    static member findSFLinkQual (i: int, qSeep: float, fEvap: float, tStep: float) : unit =
        let mutable j : int = 0
        let mutable p : int = 0
        let mutable c1 : float = 0.0
        let mutable c2 : float = 0.0
        let mutable lossRate : float = 0.0
        j <- Link.[i].node1
        p <- 0
        while (p < Nobjects.[POLLUT]) do
            c1 <- Node.[j].newQual.[p]
            S.massbal_addSeepageLoss(p, (qSeep * c1))
            c1 <- (c1 * fEvap)
            c2 <- c1
            if (Pollut.[p].kDecay > 0.0) then
                c2 <- (c1 * Libm.exp(((-(Pollut.[p].kDecay)) * tStep)))
                c2 <- ((if (((0.0) >= (c2))) then (0.0) else (c2)))
                lossRate <- (((c1 - c2)) * Link.[i].newFlow)
