            roadWidth <- Weir.[k].roadWidth
            roadSurf <- Weir.[k].roadSurface
            cD <- Weir.[k].cDisch1
            if (UnitSystem = SI) then
                cD <- (cD / 0.552)
            useVariableCd <- 0
            if ((roadWidth > 0.0) && (roadSurf >= 1)) then
