                dqdh <- ((1.5 * q) / hWr)
            Link.[j].dqdh <- dqdh
            Link.[j].newDepth <- ((if ((((h1 - hRoad)) >= (0.0))) then ((h1 - hRoad)) else (0.0)))
            Link.[j].flowClass <- SUBCRITICAL
            if (hRoad > h2) then
                if (dir = 1.0) then
                    Link.[j].flowClass <- DN_CRITICAL
                else
                    Link.[j].flowClass <- UP_CRITICAL
            __rv <- (dir * q)
        __rv

    // roadway.c:146
    static member getCd (hWr: float, ht: float, roadWidth: float, roadSurf: int) : float =
        let mutable __rv : float = 0.0
        let mutable kT : float = 0.0
        let mutable hL : float = 0.0
        let mutable htH : float = 0.0
        let mutable cR : float = 0.0
        kT <- 1.0
        if (hWr <= 0.0) then
            __rv <- 0.0
        else
            hL <- (hWr / roadWidth)
            if (hL <= 0.15) then
                if (roadSurf = PAVED) then
                    cR <- S.getY(hWr, Cr_Low_Paved, N_Cr_Low_Paved)
                else
                    cR <- S.getY(hWr, Cr_Low_Gravel, N_Cr_Low_Gravel)
            elif (roadSurf = PAVED) then
                cR <- S.getY(hL, Cr_High_Paved, N_Cr_High_Paved)
            else
                cR <- S.getY(hL, Cr_High_Gravel, N_Cr_High_Gravel)
            if (ht > 0.0) then
                htH <- (ht / hWr)
                if (roadSurf = PAVED) then
                    kT <- S.getY(htH, Kt_Paved, N_Kt_Paved)
                else
                    kT <- S.getY(htH, Kt_Gravel, N_Kt_Gravel)
            __rv <- (cR * kT)
        __rv

