        let mutable dy : float = 0.0
        let mutable __ret = false
        if (x <= table.[0].[0]) then
            __rv <- table.[0].[1]
        elif (x >= (table.[(n_2 - 1)]).[0]) then
            __rv <- (table.[(n_2 - 1)]).[1]
        else
            i <- 1
            while not (__ret) && (i < n_2) do
                if (x <= table.[i].[0]) then
                    x1 <- (table.[(i - 1)]).[0]
                    dx <- (table.[i].[0] - x1)
                    y1 <- (table.[(i - 1)]).[1]
                    dy <- (table.[i].[1] - y1)
                    __rv <- (y1 + ((((x - x1)) * dy) / dx))
                    __ret <- true
                if not (__ret) then
                    i <- i + 1
            if not (__ret) then
                __rv <- (table.[(n_2 - 1)]).[1]
        __rv

