                i <- (i + gap)
            gap <- (gap / 2)
        i <- 0
        while (i < (NumEvents - 1)) do
            if (Event.[i].end_ > (Event.[(i + 1)]).start) then
                Event.[i].end_ <- (Event.[(i + 1)]).start
            i <- i + 1

