    // stats.c:647
    static member stats_updateLinkStats (j: int, tStep: float, aDate: float) : unit =
        let mutable k : int = 0
        let mutable q : float = 0.0
        let mutable v : float = 0.0
        let mutable dq : float = 0.0
        dq <- (Link.[j].newFlow - Link.[j].oldFlow)
        q <- Math.Abs(Link.[j].newFlow)
        if (q > LinkStats.[j].maxFlow) then
            LinkStats.[j].maxFlow <- q
            LinkStats.[j].maxFlowDate <- aDate
        v <- S.link_getVelocity(j, q, Link.[j].newDepth)
        if (v > LinkStats.[j].maxVeloc) then
            LinkStats.[j].maxVeloc <- v
        if (Link.[j].newDepth > LinkStats.[j].maxDepth) then
            LinkStats.[j].maxDepth <- Link.[j].newDepth
        if (Link.[j].type_ = PUMP) then
            if (q >= Link.[j].qFull) then
                LinkStats.[j].timeFullFlow <- (LinkStats.[j].timeFullFlow + tStep)
            if (q > 0.001) then
                k <- Link.[j].subIndex
                PumpStats.[k].minFlow <- ((if (((PumpStats.[k].minFlow) <= (q))) then (PumpStats.[k].minFlow) else (q)))
                PumpStats.[k].maxFlow <- LinkStats.[j].maxFlow
                PumpStats.[k].avgFlow <- (PumpStats.[k].avgFlow + q)
                PumpStats.[k].volume <- (PumpStats.[k].volume + (q * tStep))
                PumpStats.[k].utilized <- (PumpStats.[k].utilized + tStep)
                PumpStats.[k].energy <- (PumpStats.[k].energy + ((S.link_getPower(j) * tStep) / 3600.0))
                if (Link.[j].flowClass = DN_DRY) then
                    PumpStats.[k].offCurveLow <- (PumpStats.[k].offCurveLow + tStep)
                if (Link.[j].flowClass = UP_DRY) then
                    PumpStats.[k].offCurveHigh <- (PumpStats.[k].offCurveHigh + tStep)
                if (Link.[j].oldFlow < 0.001) then
                    PumpStats.[k].startUps <- PumpStats.[k].startUps + 1
                PumpStats.[k].totalPeriods <- PumpStats.[k].totalPeriods + 1
                LinkStats.[j].timeSurcharged <- (LinkStats.[j].timeSurcharged + tStep)
                LinkStats.[j].timeFullUpstream <- (LinkStats.[j].timeFullUpstream + tStep)
                LinkStats.[j].timeFullDnstream <- (LinkStats.[j].timeFullDnstream + tStep)
        elif (Link.[j].type_ = CONDUIT) then
            if (Link.[j].normalFlow <> 0) then
                LinkStats.[j].timeNormalFlow <- (LinkStats.[j].timeNormalFlow + tStep)
            if (Link.[j].inletControl <> 0) then
                LinkStats.[j].timeInletControl <- (LinkStats.[j].timeInletControl + tStep)
            k <- Link.[j].flowClass
            if ((k >= 0) && (k < MAX_FLOW_CLASSES)) then
                LinkStats.[j].timeInFlowClass.[k] <- (LinkStats.[j].timeInFlowClass.[k] + tStep)
            k <- Link.[j].subIndex
            if (q >= (Link.[j].qFull * float (Conduit.[k].barrels))) then
                LinkStats.[j].timeFullFlow <- (LinkStats.[j].timeFullFlow + tStep)
            if (Conduit.[k].capacityLimited <> 0) then
                LinkStats.[j].timeCapacityLimited <- (LinkStats.[j].timeCapacityLimited + tStep)
            match Conduit.[k].fullState with
            | 10 ->
                LinkStats.[j].timeSurcharged <- (LinkStats.[j].timeSurcharged + tStep)
                LinkStats.[j].timeFullUpstream <- (LinkStats.[j].timeFullUpstream + tStep)
                LinkStats.[j].timeFullDnstream <- (LinkStats.[j].timeFullDnstream + tStep)
            | 8 ->
                LinkStats.[j].timeFullUpstream <- (LinkStats.[j].timeFullUpstream + tStep)
            | 9 ->
                LinkStats.[j].timeFullDnstream <- (LinkStats.[j].timeFullDnstream + tStep)
            | _ ->
                ()
            if (Link.[j].xsect.type_ = STREET_XSECT) then
                LinkStats.[j].maxStreetFilled <- ((if (((LinkStats.[j].maxStreetFilled) >= (S.street_getExtentFilled(j)))) then (LinkStats.[j].maxStreetFilled) else (S.street_getExtentFilled(j))))
        k <- LinkStats.[j].flowTurnSign
        LinkStats.[j].flowTurnSign <- ((if (((dq) < float (0))) then ((-(1))) else (1)))
        if ((Math.Abs(dq) > 0.001) && ((k * LinkStats.[j].flowTurnSign) < 0)) then
            LinkStats.[j].flowTurns <- LinkStats.[j].flowTurns + 1L

    // stats.c:756
    static member stats_findMaxStats () : unit =
        let mutable j : int = 0
        let mutable x : float = 0.0
        let mutable z : float = 0.0
        let mutable stepCount : float = 0.0
        j <- 0
        while (j < 5) do
            MaxMassBalErrs.[j].objType <- NODE
            MaxMassBalErrs.[j].index <- (-(1))
            MaxMassBalErrs.[j].value <- (-(1.0))
            MaxCourantCrit.[j].index <- (-(1))
            MaxCourantCrit.[j].value <- (-(1.0))
            MaxFlowTurns.[j].index <- (-(1))
            MaxFlowTurns.[j].value <- (-(1.0))
            MaxNonConverged.[j].index <- (-(1))
            MaxNonConverged.[j].value <- 0.0
            j <- j + 1
        if (ReportStepCount > int64 (2)) then
            stepCount <- float (ReportStepCount)
            z <- (100.0 / (((2.0 / 3.0) * ((stepCount - 2.0)))))
            j <- 0
            while (j < Nobjects.[LINK]) do
                x <- (float (LinkStats.[j].flowTurns) * z)
                S.stats_updateMaxStats(MaxFlowTurns, LINK, j, x)
                j <- j + 1
        j <- 0
        while (j < Nobjects.[NODE]) do
            if (Node.[j].degree <= 0) then
                ()
            elif (NodeInflow.[j] <= 0.1) then
                ()
            else
                if (NodeInflow.[j] > 0.0) then
                    x <- (1.0 - (NodeOutflow.[j] / NodeInflow.[j]))
                elif (NodeOutflow.[j] > 0.0) then
                    x <- (-(1.0))
                else
                    x <- 0.0
                S.stats_updateMaxStats(MaxMassBalErrs, NODE, j, (100.0 * x))
            j <- j + 1
        stepCount <- float (TimeStepStats.timeStepCount)
        if (RouteModel = DW) then
            j <- 0
            while (j < Nobjects.[NODE]) do
                S.stats_updateMaxStats(MaxNonConverged, NODE, j, (float (NodeStats.[j].nonConvergedCount) / stepCount))
                j <- j + 1
        if ((RouteModel <> DW) || (CourantFactor = 0.0)) then
            ()
        elif (stepCount = float (0)) then
            ()
        else
            j <- 0
            while (j < Nobjects.[NODE]) do
                x <- (NodeStats.[j].timeCourantCritical / stepCount)
                S.stats_updateMaxStats(MaxCourantCrit, NODE, j, (100.0 * x))
                j <- j + 1
            j <- 0
            while (j < Nobjects.[LINK]) do
                x <- (LinkStats.[j].timeCourantCritical / stepCount)
                S.stats_updateMaxStats(MaxCourantCrit, LINK, j, (100.0 * x))
                j <- j + 1

    // stats.c:841
    static member stats_updateMaxStats (maxStats: TMaxStats[], i: int, j: int, x: float) : unit =
        let mutable k : int = 0
        let mutable maxStats1 : TMaxStats = Unchecked.defaultof<TMaxStats>
        let mutable maxStats2 : TMaxStats = Unchecked.defaultof<TMaxStats>
        maxStats1 <- TMaxStats()
        maxStats2 <- TMaxStats()
        maxStats1.objType <- i
        maxStats1.index <- j
        maxStats1.value <- x
        k <- 0
        while (k < 5) do
            if (Math.Abs(maxStats1.value) > Math.Abs(maxStats.[k].value)) then
                maxStats2 <- maxStats.[k].Clone()
                maxStats.[k] <- maxStats1.Clone()
                maxStats1 <- maxStats2.Clone()
            k <- k + 1

    // statsrpt.c:84
    static member statsrpt_writeReport () : unit =
        if ((FlowUnits = MGD) || (FlowUnits = CMS)) then
            ignore (O.sstrncpy(FlowFmt, L534, uint64 (5)))
        else
            ignore (O.sstrncpy(FlowFmt, L535, uint64 (5)))
        if (UnitSystem = US) then
            Vcf <- (7.48 / 1.0e6)
        else
