        if (Nobjects.[SUBCATCH] > 0) then
            if (((not (IgnoreRainfall <> 0)) || (((Nobjects.[SNOWMELT] > 0) && (not (IgnoreSnowmelt <> 0))))) || (((Nobjects.[AQUIFER] > 0) && (not (IgnoreGwater <> 0))))) then
                S.writeSubcatchRunoff()
                S.lid_writeWaterBalance()
                if (not (IgnoreGwater <> 0)) then
                    S.writeGroundwater()
                if ((Nobjects.[POLLUT] > 0) && (not (IgnoreQuality <> 0))) then
                    S.writeSubcatchLoads()
        if ((Nobjects.[LINK] > 0) && (not (IgnoreRouting <> 0))) then
            S.writeNodeDepths()
            S.writeNodeFlows()
            if (RouteModel = DW) then
                S.writeNodeSurcharge()
            S.writeNodeFlooding()
            S.writeStorageVolumes()
            S.writeOutfallLoads()
            S.inlet_writeStatsReport()
            S.writeLinkFlows()
            S.writeFlowClass()
            S.writeLinkSurcharge()
            S.writePumpFlows()
            if ((Nobjects.[POLLUT] > 0) && (not (IgnoreQuality <> 0))) then
                S.writeLinkLoads()

